"""RDKE Core RDK Components generator."""
import json
from build import ROOT, esc, hero, load, shell, status_explainer


def build_components() -> None:
    source = load("components.json")
    records = source.get("components", [])
    data = [[item.get("name", ""), item.get("category", ""), item.get("layer", ""), item.get("type") or "core", item.get("releaseTag") or "develop", (item.get("url") or [""])[0]] for item in records]
    categories = sorted({row[1] for row in data})
    layers = sorted({row[2] for row in data})
    body = hero("Core Components", "Components Catalog", "The middleware-layer components of RDK-E. Together they provide a single, consistent implementation of core Entertainment device functionality, built on the Thunder framework, exposing standardized APIs to the application layer, and integrating with the vendor layer through the HAL. Delivered as binary packages, these components can be developed and updated independently of the other layers.")
    body += f'''<style>.catalog-stats{{grid-template-columns:repeat(3,minmax(0,1fr))}}.api-controls{{display:flex;flex-direction:column;align-items:stretch;gap:16px}}.api-controls details[open]{{z-index:10}}.api-controls details[open] dl{{position:absolute!important;left:0!important;right:auto!important;top:calc(100% + 8px)!important;width:min(420px,calc(100vw - 40px))!important;margin:0!important}}.api-controls>.toolbar{{display:grid;grid-template-columns:minmax(0,2fr) repeat(2,minmax(0,1fr));gap:12px;width:100%;margin:0;min-width:0}}.api-controls>.toolbar input,.api-controls>.toolbar select{{width:100%;min-width:0;margin:0}}.catalog-stats .stat{{min-height:112px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:5px}}.catalog-stats .stat strong{{line-height:1;font-size:2rem}}.catalog-stats .stat span{{line-height:1.2}}@media(max-width:760px){{.catalog-stats{{grid-template-columns:1fr}}.api-controls>.toolbar{{grid-template-columns:1fr}}}}</style><section class="section"><div class="api-controls"><div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap"><span style="display:inline-flex;align-items:center;padding:9px 14px;border:1px solid #edcf7a;border-radius:5px;background:#fff4d8;color:#8a5a00;font:700 .75rem/1 JetBrains Mono,monospace;letter-spacing:.04em"><span style="color:#9a731f;font-weight:600;margin-right:6px">Catalog status:</span> Draft</span>{status_explainer()}</div><div class="toolbar" style="margin:0"><input id="search" type="search" placeholder="Search components" aria-label="Search components"><select id="category"><option value="">All categories</option>{''.join(f'<option>{esc(item)}</option>' for item in categories)}</select><select id="layer"><option value="">All layers</option>{''.join(f'<option>{esc(item)}</option>' for item in layers)}</select></div></div><div class="stats catalog-stats"><div class="stat"><strong>{len(data)}</strong><span>Components</span></div><div class="stat"><strong>{len(categories)}</strong><span>Categories</span></div><div class="stat"><strong>{len(layers)}</strong><span>Layers</span></div></div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Category</th><th>Layer</th><th>Type</th><th>Version</th><th>Source</th></tr></thead><tbody id="rows"></tbody></table></div></section>'''
    rows = json.dumps(data, ensure_ascii=True)
    script = f'''<script>const DATA={rows};const esc=s=>{{const d=document.createElement('div');d.textContent=s;return d.innerHTML}};const search=document.querySelector('#search'),category=document.querySelector('#category'),layer=document.querySelector('#layer');function render(){{const q=search.value.toLowerCase();const rows=DATA.filter(c=>(!q||c.join(' ').toLowerCase().includes(q))&&(!category.value||c[1]===category.value)&&(!layer.value||c[2]===layer.value));document.querySelector('#rows').innerHTML=rows.length?rows.map(c=>`<tr><td>${{esc(c[0])}}</td><td><span class="pill">${{esc(c[1])}}</span></td><td>${{esc(c[2])}}</td><td><span class="pill core">${{esc(c[3])}}</span></td><td>${{esc(c[4])}}</td><td><a href="${{esc(c[5])}}" target="_blank" rel="noopener">${{esc(c[5])}}</a></td></tr>`).join(''):'<tr><td class="empty" colspan="6">No components match the current filters.</td></tr>'}}[search,category,layer].forEach(e=>e.addEventListener('input',render));render()</script>'''
    body = body.replace('<section class="section">', '<style>.pill.core{background:#dff7ea;color:#1d6b43;border:1px solid #a8e1bd}</style><section class="section">', 1)
    (ROOT / "component-registry.html").write_text(shell("Core RDK Components | RDKE", "components", body + script), encoding="utf-8")

if __name__ == "__main__":
    build_components()
